var ATTR_KEYS = ['IMEI', 'IMSI', 'Model', 'latitude', 'longitude', 'gps_time', 'idc_alarm', 'vdc_alarm'];
var LIVE_KEYS = ['idc_input', 'vdc_input', 'battery', 'signal', 'interrupt', 'interrupt_level', 'time'];

function toNumber(v) {
  if (v === null || v === undefined || v === '') return null;
  var n = Number(v);
  return isNaN(n) ? null : n;
}

function parseScaleCm(md) {
  var raw = md['ss_probe_full_scale_cm'];
  var n = toNumber(raw);
  if (n === null || n <= 0) return 100;
  return n;
}

function depthFromIdc(idc, scaleCm) {
  var n = toNumber(idc);
  if (n === null || n < 4) return null;
  var depth = (n - 4) / 16 * scaleCm;
  if (depth < 0) depth = 0;
  if (depth > scaleCm) depth = scaleCm;
  return depth;
}

function applyDepth(values, idc, scaleCm) {
  var depthCm = depthFromIdc(idc, scaleCm);
  if (depthCm === null) return values;
  values['depth_cm'] = Math.round(depthCm * 1000) / 1000;
  values['depth_mm'] = Math.round(depthCm * 10 * 1000) / 1000;
  return values;
}

function isoToTs(iso) {
  if (iso === null || iso === undefined || iso === '') return null;
  var t = new Date(String(iso)).getTime();
  return isNaN(t) ? null : t;
}

function copyMetadata(md) {
  var out = {};
  for (var k in md) {
    if (Object.prototype.hasOwnProperty.call(md, k)) out[k] = md[k];
  }
  return out;
}

var scaleCm = parseScaleCm(metadata);
var outs = [];

var attrMsg = {};
var hasAttr = false;
for (var ai = 0; ai < ATTR_KEYS.length; ai++) {
  var ak = ATTR_KEYS[ai];
  if (msg[ak] !== undefined && msg[ak] !== null) {
    attrMsg[ak] = msg[ak];
    hasAttr = true;
  }
}
if (hasAttr) {
  outs.push({
    msg: attrMsg,
    metadata: copyMetadata(metadata),
    msgType: 'POST_ATTRIBUTES_REQUEST'
  });
}

var liveValues = {};
for (var li = 0; li < LIVE_KEYS.length; li++) {
  var lk = LIVE_KEYS[li];
  if (msg[lk] !== undefined && msg[lk] !== null) {
    liveValues[lk] = msg[lk];
  }
}
liveValues = applyDepth(liveValues, msg['idc_input'], scaleCm);

var telemetryPoints = [];
var liveTs = isoToTs(msg['time']);
if (Object.keys(liveValues).length > 0) {
  if (liveTs !== null) {
    telemetryPoints.push({ ts: liveTs, values: liveValues });
  } else {
    var liveMeta = copyMetadata(metadata);
    outs.push({
      msg: liveValues,
      metadata: liveMeta,
      msgType: 'POST_TELEMETRY_REQUEST'
    });
  }
}

for (var i = 1; i <= 32; i++) {
  var key = String(i);
  var slot = msg[key];
  if (slot === undefined || slot === null) continue;
  if (!Array.isArray(slot) || slot.length < 3) continue;
  var idc = slot[0];
  var vdc = slot[1];
  var sampleTs = isoToTs(slot[2]);
  if (sampleTs === null) continue;
  var hist = { idc_input: idc, vdc_input: vdc };
  hist = applyDepth(hist, idc, scaleCm);
  telemetryPoints.push({ ts: sampleTs, values: hist });
}

if (telemetryPoints.length > 0) {
  outs.push({
    msg: telemetryPoints,
    metadata: copyMetadata(metadata),
    msgType: 'POST_TELEMETRY_REQUEST'
  });
}

if (outs.length === 0) {
  return { msg: msg, metadata: metadata, msgType: msgType };
}
return outs;

